const fileNames={assembly:'exploded-surface-assembly.svg',workflow:'modular-finishing-workflow.svg',orthographic:'orthographic-folded-panel.svg'};
const study=document.querySelector('#blueprint-study');let cleanup=()=>{};
function art(key,alt){return `<img class="technical-image" src="assets/${fileNames[key]}" alt="${alt||'Conceptual technical drawing of metal components'}" width="900" height="620">`}
function guide(d){return `<section id="specifications" class="designer-guide"><div class="guide-title-row"><div><span class="overline">For the web designer</span><h2>${d.num} / ${d.name}<br>The visual rules.</h2><p>${d.summary}</p></div><span class="guide-counter">STYLE SHEET<br>NS—BP / ${d.num}</span></div><div class="guide-grid"><article class="guide-block"><h3>01 / Typography & spacing</h3><div class="type-specimen">Aa Bb Cc<br><span>0123456789</span></div><p>One monospaced family throughout. Use weight, scale, and space to separate headlines, body copy, and drawing labels.</p><table class="spec-table"><tbody><tr><th>Typeface</th><td>${d.font}</td></tr><tr><th>Weights</th><td>${d.weight}</td></tr><tr><th>Target scale</th><td>${d.typeSizes}</td></tr><tr><th>Spacing scale</th><td>${d.spacing}</td></tr><tr><th>Body rhythm</th><td>1.7–1.9 line height</td></tr></tbody></table></article><article class="guide-block"><h3>02 / Ink & illustration</h3><div class="palette">${d.palette.map((c,i)=>`<div class="color-token"><i style="background:${c}"></i>${c}<br>${['Paper','Text','Secondary','Drawing'][i]}</div>`).join('')}</div><p>${d.art}</p><div class="stroke-key"><div><i></i>Primary edge / ${d.line}</div><div><i></i>Secondary edge / 0.75 px</div><div><i></i>Construction / 0.5 px, dashed</div></div><p>Text stays legible. Pale gray belongs to drawings and guide marks, not essential copy.</p></article><article class="guide-block"><h3>03 / Composition & motion</h3><div class="motion-diagram" aria-hidden="true"><svg viewBox="0 0 300 100"><path d="M25 20H115Q135 20 135 40V55Q135 75 155 75H270" stroke="#d8e1da"/><path class="sample-line" d="M25 20H115Q135 20 135 40V55Q135 75 155 75H270"/><circle cx="25" cy="20" r="4"/><rect x="260" y="66" width="18" height="18"/><path d="M258 70l9 5-9 5"/></svg></div><p>${d.layout}</p><ul><li>${d.motion}</li><li>Mobile: stack the drawing below the copy and preserve the reading order.</li><li>Reduced motion: show the completed route and a stationary logo.</li></ul></article></div><div class="guide-takeaway"><h3>DESIGNER’S TAKEAWAY ↗</h3><p>${d.handoff}</p></div><div class="guide-actions"><a href="assets/North-State-Blueprint-Style-Guide.md" download>Download all three style sheets ↗</a><button class="replay-study">Replay the page study ↑</button></div></section>`}
function render(){cleanup();const id=location.hash.slice(1);const key=directions[id]?id:'whiteprint',d=directions[key];document.body.className=`direction-${key}`;document.title=`${d.num} ${d.name} — North State blueprint studies`;document.querySelectorAll('[data-concept]').forEach(a=>{if(a.dataset.concept===key)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});window.scrollTo({top:0,behavior:'instant'});
 study.innerHTML=`<div class="study-context"><div><p class="context-title">${d.num} / ${d.name.toUpperCase()}</p><p>${d.summary}</p></div><span class="direction-badge">${d.badge}</span></div><section class="specimen" aria-label="${d.name} homepage concept"><svg class="draft-paths" aria-hidden="true"></svg><div class="specimen-inner"><div class="specimen-topline"><span>North State<br>Powder Coating</span><span>Burlington, NC<br>Surface studies / ${d.num}</span></div><a class="draft-logo" href="index.html" aria-label="North State original concept collection"><img src="assets/northstate-logo.svg" alt="North State Powder Coating"></a><section class="specimen-hero"><div class="hero-wording"><span class="plate-label">${d.kicker}</span><h1>${d.headline}</h1><p>Professional powder coating for metal.<br>Custom solutions, protective finishing,<br>and a personal approach.</p><button class="text-action" data-scroll="practice">Follow the details <span aria-hidden="true">↘</span></button></div><figure class="hero-drawing"><div class="drawing-frame">${art(d.hero,d.heroAlt)}</div><span class="figure-number">NS / FIG. ${d.num}.01</span><figcaption class="drawing-caption">${d.tags.map(t=>`<span>${t}</span>`).join('')}</figcaption></figure></section><div class="hero-bottom"><span class="route-hint">A finish worth following.</span><span>Conceptual line studies<br>Scroll to trace the connection ↓</span></div><section class="ecosystem" id="practice"><h2 class="ecosystem-heading">${d.section}</h2><div class="service-rows"><article class="service-row" data-step="01"><h3>The surface.</h3><p>Professional powder coating for industrial equipment, machinery, and your next metal project.</p><div class="service-detail"><span class="detail-label">Purpose</span><span>Custom solutions<br>Considered details</span></div><div class="service-detail"><span class="detail-label">Focus</span><div class="micro-tags"><span>METAL SURFACES</span><span>CUSTOM COATING</span></div></div></article><article class="service-row" data-step="02"><h3>The protection.</h3><p>A protective finish that helps metal stand up to corrosion and wear.</p><div class="service-detail"><span class="detail-label">Purpose</span><span>Lasting protection<br>Quality materials</span></div><div class="service-detail"><span class="detail-label">Focus</span><div class="micro-tags"><span>PROTECTIVE FINISHING</span><span>SURFACE CARE</span></div></div></article><article class="service-row" data-step="03"><h3>The people.</h3><p>North Carolina based. Personal service and environmentally conscious coating solutions.</p><div class="service-detail"><span class="detail-label">Purpose</span><span>Local relationships<br>Personal attention</span></div><div class="service-detail"><span class="detail-label">Focus</span><div class="micro-tags"><span>BURLINGTON, NC</span><span>LET’S TALK</span></div></div></article></div><figure class="ecosystem-drawing"><div class="drawing-frame">${art(d.secondary)}</div><figcaption class="process-caption">FIG. ${d.num}.02 / ${d.secondary==='assembly'?'A study in surfaces, layers, and the relationships between them.':'A connected arrangement of finishing modules.'}<br><br>Illustrative geometry. Not a drawing of North State’s actual equipment.</figcaption></figure></section><section class="contact-study" id="conversation"><span class="overline">Next / your project</span><h2>${d.contact}</h2><a class="text-action" href="mailto:Jesse@northstatepc.com">Start a conversation <span aria-hidden="true">↗</span></a><div class="contact-grid"><p><a href="mailto:Jesse@northstatepc.com">Jesse@northstatepc.com</a><a href="tel:+19198012079">(919) 801-2079</a></p><address>1305 Graham St<br>Burlington, North Carolina</address></div><div class="contact-rule">NORTH STATE POWDER COATING / LOCAL SERVICE. LASTING CARE.</div></section><div class="specimen-end"><span>END OF PAGE STUDY / ${d.num}</span><span>MONOCHROME · MONOSPACED · TECHNICAL</span></div></div></section>${guide(d)}`;
 document.querySelectorAll('[data-scroll]').forEach(button=>button.onclick=()=>document.getElementById(button.dataset.scroll).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'}));document.querySelector('.replay-study').onclick=()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});
 cleanup=animateDrawing(key);
}
function animateDrawing(key){const specimen=document.querySelector('.specimen'),svg=document.querySelector('.draft-paths'),logo=document.querySelector('.draft-logo'),hero=document.querySelector('.hero-bottom'),practice=document.querySelector('.ecosystem'),contact=document.querySelector('.contact-study'),media=matchMedia('(prefers-reduced-motion:reduce)');let paths=[],raf=0,disposed=false,start=0;const ns='http://www.w3.org/2000/svg';
 function node(tag,attrs){const n=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));return n}
 function measure(){if(disposed)return;svg.replaceChildren();paths=[];const origin=specimen.getBoundingClientRect();start=origin.top+scrollY;const w=specimen.clientWidth,h=specimen.clientHeight;svg.setAttribute('viewBox',`0 0 ${w} ${h}`);const hr=hero.getBoundingClientRect(),pr=practice.getBoundingClientRect(),cr=contact.getBoundingClientRect();const pairs=[{x1:w*.5,y1:hr.bottom-origin.top+6,x2:pr.left-origin.left+18,y2:pr.top-origin.top+115},{x1:pr.left-origin.left+pr.width*.44,y1:pr.bottom-origin.top+15,x2:cr.left-origin.left+cr.width*.5,y2:cr.top-origin.top-16}];pairs.forEach(p=>{const gap=p.y2-p.y1,mid=p.y1+gap*.55;let d=key==='assembly'?`M${p.x1} ${p.y1}V${mid-15}Q${p.x1} ${mid} ${p.x1-15} ${mid}H${p.x2+15}Q${p.x2} ${mid} ${p.x2} ${mid+15}V${p.y2}`:`M${p.x1} ${p.y1}V${mid}H${p.x2}V${p.y2}`;if(p.y2<=p.y1){p.y2=p.y1+60;d=`M${p.x1} ${p.y1}L${p.x2} ${p.y2}`}const ghost=node('path',{d,class:'draft-ghost'}),line=node('path',{d,class:'draft-line'}),head=node('path',{d:'M-5 -8L0 0L5 -8',class:'draft-arrow'});svg.append(ghost,line,head);const len=line.getTotalLength();line.style.strokeDasharray=len;paths.push({line,head,len,...p})});draw()}
 function draw(){raf=0;if(disposed)return;const inner=document.querySelector('.specimen-inner').getBoundingClientRect(),mobile=document.documentElement.clientWidth<=760,initialWidth=mobile?108:134,finalWidth=mobile?65:75,anchorY=inner.top+scrollY+(mobile?65:38),anchorX=inner.left+(inner.width-initialWidth)/2,progress=media.matches?1:Math.max(0,Math.min(1,(scrollY-Math.max(0,anchorY-200))/350)),ease=progress*progress*(3-2*progress),targetX=document.documentElement.clientWidth-finalWidth-(mobile?22:document.documentElement.clientWidth*.045);logo.style.position='fixed';logo.style.transform='none';logo.style.left=`${anchorX+(targetX-anchorX)*ease}px`;logo.style.top=`${(anchorY-scrollY)*(1-ease)+(mobile?76:85)*ease}px`;logo.style.width=`${initialWidth+(finalWidth-initialWidth)*ease}px`;logo.style.visibility=scrollY>start+specimen.clientHeight-160?'hidden':'visible';logo.classList.toggle('is-pinned',progress>.95);
 const cursor=scrollY+innerHeight*.76-start;paths.forEach(p=>{const amount=media.matches?1:Math.max(0,Math.min(1,(cursor-p.y1)/(p.y2-p.y1))),length=p.len*amount;p.line.style.strokeDashoffset=p.len-length;p.head.style.opacity=amount>0?'1':'0';const a=p.line.getPointAtLength(length),b=p.line.getPointAtLength(Math.max(0,length-1));p.head.setAttribute('transform',`translate(${a.x},${a.y}) rotate(${Math.atan2(a.y-b.y,a.x-b.x)*180/Math.PI-90})`)});
 }
 function scroll(){if(!raf)raf=requestAnimationFrame(draw)}const observer=new ResizeObserver(measure);observer.observe(specimen);window.addEventListener('scroll',scroll,{passive:true});window.addEventListener('resize',measure);media.addEventListener('change',draw);document.fonts.ready.then(()=>{if(!disposed)measure()});measure();return ()=>{disposed=true;cancelAnimationFrame(raf);observer.disconnect();window.removeEventListener('scroll',scroll);window.removeEventListener('resize',measure);media.removeEventListener('change',draw)};
}
window.addEventListener('hashchange',()=>{if(directions[location.hash.slice(1)])render()});document.querySelector('.skip-study').onclick=event=>{event.preventDefault();const main=document.querySelector('#content');main.setAttribute('tabindex','-1');main.focus({preventScroll:true});main.scrollIntoView({behavior:'instant'})};render();
